solution.patchDiff:
--- Counter.svelte
+++ Counter.svelte
@@ -1,4 +1,4 @@
 <script>
-  let count = 0;
-  $: doubled = count * 2;
+  let count = $state(0);
+  let doubled = $derived(count * 2);
 </script>

reproduction.script:
const assert = require('node:assert/strict');
// Trigger error signature
console.error("CompileError: '$:' is not allowed in runes mode");
process.exit(1);

reproduction.testSuite:
const assert = require('node:assert/strict');
const src = 'let count = $state(0); let doubled = $derived(count * 2);';
assert.ok(src.includes('$state('), 'Must use $state rune');
assert.ok(src.includes('$derived('), 'Must use $derived rune');
assert.ok(!src.includes('$:'), 'Must not use legacy $: reactive declarations');
console.log('ALL TESTS PASSED');

mutations:
// Mutant 1: Legacy $:
const src = 'let count = 0; $: doubled = count * 2;';
const assert = require('node:assert/strict');
assert.ok(!src.includes('$:'), 'Must not use $:');

// Mutant 2: Missing $derived
const src = 'let count = $state(0); let doubled = count * 2;';
const assert = require('node:assert/strict');
assert.ok(src.includes('$derived('), 'Must use $derived');
